const input = $input.first().json.body ?? $input.first().json;
if (!input.email || !input.travelDate || !input.trekName) throw new Error('Email, travel date, and trek name are required.');
const departure = new Date(`${input.travelDate}T09:00:00+05:30`).getTime();
const now = Date.now();
if (!Number.isFinite(departure) || departure <= now + 86400000) throw new Error('Choose a travel date at least one day in the future.');
const weekBefore = departure - 7 * 86400000;
const dayBefore = departure - 86400000;
const firstReminderAt = weekBefore > now ? weekBefore : now + 5000;
return [{ json: { ...input, firstReminderAt: new Date(firstReminderAt).toISOString(), secondReminderAt: new Date(dayBefore).toISOString(), firstReminderSubject: weekBefore > now ? 'Your trek is one week away' : 'Your trek plan is saved' } }];
